package nodes

import (
	"errors"
	"fmt"
	"regexp"
	"strings"

	clabtypes "github.com/srl-labs/containerlab/types"
	"gopkg.in/yaml.v2"
)

// KindSpecificConfigType is a kind's config type, registered with
